#requires -Version 5.1
# B4-02: integrated existing-parser acceptance, generated bytes only.
# Frozen R1: Issue #71 comment 6851861589. No new inference/source identity.
$b402Seeds=@(202611,202612,202613)
$b402Lfn=@{TP=0;FP=0;FN=0;TN=0}
$b402Deletion=@{TP=0;FP=0;FN=0;TN=0}
$b402Orphan=@{TP=0;FP=0;FN=0;TN=0}
$b402Scans=0; $b402Returned=0L; $b402Directory=0L
$b402Calls=0L; $b402Retained=0L; $b402UnknownPaths=0
$b402Hashes=New-Object System.Collections.ArrayList
$b402Elapsed=0L
foreach($b402Seed in $b402Seeds) {
    $b402Fixture=New-ChappyA3DDamagedFixture -Case M00 -Seed $b402Seed
    $b402Root=[int](New-ChappyA3DCleanFixture -Seed $b402Seed).layout.rootOffsetBytes
    if($b402Root -ne 57856){throw 'B4-02 artificial root moved'}
    foreach($b402Mode in @('valid','checksum_corrupt')) {
        [byte[]]$b402Image=[byte[]]$b402Fixture.image.Clone()
        $b402OrphanAt=$b402Root+(19-2)*512
        $b402DecoyAt=$b402Root+(20-2)*512
        foreach($b402At in @(($b402Root+96),($b402Root+128),($b402Root+160),($b402Root+192),$b402OrphanAt,$b402DecoyAt)){
            if($b402Image[$b402At] -ne 0){throw 'B4-02 reserved synthetic slot was occupied'}
        }
        [byte[]]$b402Live=New-ShortB 'LONGNAMETXT' 0x20 30 44
        $b402LfnSlots=New-LfnB 'artificial-retained-name' $b402Live
        if($b402LfnSlots.Count -ne 2){throw 'B4-02 fixed two LFN slots changed'}
        [Array]::Copy([byte[]]$b402LfnSlots[0],0,$b402Image,$b402Root+96,32)
        [Array]::Copy([byte[]]$b402LfnSlots[1],0,$b402Image,$b402Root+128,32)
        if($b402Mode -eq 'checksum_corrupt'){
            $b402Image[$b402Root+109]=[byte](($b402Image[$b402Root+109]+1) -band 255)
        }
        [Array]::Copy($b402Live,0,$b402Image,$b402Root+160,32)
        [byte[]]$b402Deleted=New-ShortB 'DELETE  TXT' 0x20 31 18
        $b402Deleted[0]=0xE5
        [Array]::Copy($b402Deleted,0,$b402Image,$b402Root+192,32)
        [Array]::Copy((New-ShortB '.          ' 0x10 19 0),0,$b402Image,$b402OrphanAt,32)
        [Array]::Copy((New-ShortB '..         ' 0x10 0 0),0,$b402Image,$b402OrphanAt+32,32)
        [Array]::Copy((New-ShortB 'ORPHAN  TXT' 0x20 35 17),0,$b402Image,$b402OrphanAt+64,32)
        [Array]::Copy((New-ShortB 'FAKE    TXT' 0x20 36 12),0,$b402Image,$b402DecoyAt,32)
        $b402Before=Get-A3DSha256 $b402Image
        [void]$b402Hashes.Add($b402Before)
        foreach($b402Include in @($false,$true)) {
            $b402Stream=[ChappyBR4ObservedParentPositive.MeteredStream]::new($b402Image,97,-1L,128)
            try {
                $b402Args=@{
                    Stream=$b402Stream; MaxScanBytes=9728L; MaxCandidates=16
                    MaxDirectories=8; IncludeDeleted=$b402Include
                    RecordDirectoryReadSpans=$true; MaxDirectoryReadSpans=32
                    ClassifyIncompleteDirectoryReadOrigin=$true
                    RecordDirectoryPhysicalReadBytes=$true; RecordClusterCoverage=$true
                }
                $b402Watch=[Diagnostics.Stopwatch]::StartNew()
                $b402Scan=Get-ChappyDirectoryCandidates @b402Args
                $b402Graph=Get-ChappyDirectoryHierarchyEvidence -DirectoryResult $b402Scan -DetectConflictingContainerObservations -RequireObservedClusterIntervals -MaxNodes 16 -MaxEdges 16 -MaxMetadataItems 32 -MaxAncestorSteps 64
                $b402Watch.Stop(); $b402Elapsed += [long]$b402Watch.ElapsedMilliseconds
                $b402Events=@($b402Stream.Events)
                Assert-B (-not $b402Stream.CanWrite -and $b402Stream.CanRead -and
                    $b402Stream.Calls -le 128 -and $b402Stream.ReturnedBytes -le 10752L -and
                    (Test-BR4EventsMatchInput $b402Events $b402Image)) ('B4-02 synthetic readonly positive-return SHA/offset budget '+$b402Seed+' '+$b402Mode+' '+$b402Include)
                Assert-B ($b402Scan.scanIncomplete -and $b402Graph.scanIncomplete -and
                    $b402Scan.metrics.bytesRead -eq 9728L -and
                    $b402Scan.directoryPhysicalReadEvidence.streamReturnedBytes -eq 9728L -and
                    $b402Scan.directoryPhysicalReadEvidence.incompleteClusterReturnedBytes -eq 0L -and
                    $b402Stream.ReturnedBytes -eq 10752L -and $b402Stream.Calls -eq 126 -and
                    $b402Graph.metrics.probableEdgeAssertions -eq 0 -and $b402Graph.edges.Count -eq 0) ('B4-02 incomplete original coverage and no path promotion '+$b402Seed+' '+$b402Mode+' '+$b402Include)
                $b402LiveItems=@($b402Scan.items|Where-Object{
                    -not $_.isDirectory -and -not $_.deleted -and
                    $_.containerCluster -eq 2 -and $_.startCluster -eq 30 -and
                    $_.offsetBytes -eq ($b402Root+160)
                })
                $b402DeletedItems=@($b402Scan.items|Where-Object{
                    $_.deleted -and -not $_.isDirectory -and
                    $_.containerCluster -eq 2 -and $_.startCluster -eq 31
                })
                $b402OrphanFiles=@($b402Scan.items|Where-Object{
                    -not $_.isDirectory -and $_.containerCluster -eq 19 -and $_.startCluster -eq 35
                })
                $b402RealNode=@($b402Graph.nodes|Where-Object{
                    $_.cluster -eq 19 -and $_.linkStatus -eq 'orphan_candidate'
                })
                Assert-B ($b402LiveItems.Count -eq 1 -and
                    $b402OrphanFiles.Count -eq 1 -and $b402RealNode.Count -eq 1 -and
                    @($b402Scan.items|Where-Object{$_.containerCluster -eq 20}).Count -eq 0 -and
                    @($b402Graph.nodes|Where-Object{$_.cluster -eq 20}).Count -eq 0 -and
                    $b402Scan.metrics.directoryRejectReasons.insufficient_directory_evidence -ge 1) ('B4-02 accepted orphan and rejected single-entry decoy '+$b402Seed+' '+$b402Mode+' '+$b402Include)
                if($b402Mode -eq 'valid'){
                    Assert-B ($b402LiveItems[0].nameSource -eq 'lfn_validated' -and
                        $b402LiveItems[0].evidence -contains 'lfn_checksum_sequence_valid') ('B4-02 observed multi-slot LFN associated '+$b402Seed+' '+$b402Include)
                    $b402Lfn.TP++
                } else {
                    Assert-B ($b402LiveItems[0].nameSource -eq 'short_8_3' -and
                        $b402LiveItems[0].confidence -eq 'partial' -and
                        $b402LiveItems[0].evidence -contains 'lfn_rejected_short_fallback') ('B4-02 corrupt LFN falls back to retained partial alias '+$b402Seed+' '+$b402Include)
                    $b402Lfn.TN++
                }
                if($b402Include) {
                    Assert-B ($b402DeletedItems.Count -eq 1 -and
                        $b402DeletedItems[0].confidence -eq 'partial' -and
                        $b402DeletedItems[0].nameSource -eq 'deleted_short_partial' -and
                        $b402DeletedItems[0].evidence -contains 'deleted_first_character_unknown' -and
                        $b402Scan.items.Count -eq 6) ('B4-02 IncludeDeleted retains unknown-first-char candidate '+$b402Seed+' '+$b402Mode)
                    $b402Deletion.TP++
                } else {
                    Assert-B ($b402DeletedItems.Count -eq 0 -and $b402Scan.items.Count -eq 5) ('B4-02 default deleted visibility OFF, ordinary/orphan stay '+$b402Seed+' '+$b402Mode)
                    $b402Deletion.TN++
                }
                Assert-B (@($b402Graph.parentHints|Where-Object{
                    $_.childCluster -eq 19 -and $_.relationStatus -eq 'root_marker_not_path'
                }).Count -eq 1 -and
                    @($b402Scan.items|Where-Object{$null -ne $_.name -or $null -ne $_.shortName -or
                        $_.PSObject.Properties.Name -contains 'originalPath'}).Count -eq 0) ('B4-02 redacted result, orphan hint is not original path '+$b402Seed+' '+$b402Mode+' '+$b402Include)
                $b402Orphan.TP++ # one known genuine orphan container
                $b402Orphan.TN++ # one known rejected false directory
                $b402UnknownPaths++ # full original hierarchy cannot be established
                $b402Returned += [long]$b402Stream.ReturnedBytes
                $b402Directory += [long]$b402Scan.directoryPhysicalReadEvidence.streamReturnedBytes
                $b402Calls += [long]$b402Stream.Calls
                $b402Retained += [long]$b402Scan.items.Count
                $b402Scans++
                Write-Host ('B4-02 MATRIX: seed={0} LFN={1} IncludeDeleted={2} LFNsource={3} deletedRetained={4} orphan=1 decoy=0 returned={5}B originalPath=UNKNOWN' -f
                    $b402Seed,$b402Mode,$b402Include,$b402LiveItems[0].nameSource,$b402DeletedItems.Count,$b402Stream.ReturnedBytes)
            } finally { $b402Stream.Dispose() }
            Assert-B ((Get-A3DSha256 $b402Image) -ceq $b402Before) ('B4-02 generated full source SHA unchanged '+$b402Seed+' '+$b402Mode+' '+$b402Include)
        }
    }
}
Assert-B (@($b402Hashes|Select-Object -Unique).Count -eq 6 -and
    $b402Scans -eq 12 -and
    $b402Lfn.TP -eq 6 -and $b402Lfn.FP -eq 0 -and $b402Lfn.FN -eq 0 -and $b402Lfn.TN -eq 6 -and
    $b402Deletion.TP -eq 6 -and $b402Deletion.FP -eq 0 -and $b402Deletion.FN -eq 0 -and $b402Deletion.TN -eq 6 -and
    $b402Orphan.TP -eq 12 -and $b402Orphan.FP -eq 0 -and $b402Orphan.FN -eq 0 -and $b402Orphan.TN -eq 12) 'B4-02 12 LFN, 12 deleted-visibility, 24 orphan/decoy units with frozen labels'
Assert-B ($b402Returned -eq 129024L -and $b402Directory -eq 116736L -and
    $b402Calls -eq 1512L -and $b402Retained -eq 66L -and
    $b402UnknownPaths -eq 12) 'B4-02 source actual bytes/calls, 66 retained metadata and 12 unknown original paths'
Write-Host ('B4-02 ACCEPTANCE: LFN TP={0} FP={1} FN={2} TN={3}; deleted visibility TP={4} FP={5} FN={6} TN={7}; orphan/decoy TP={8} FP={9} FN={10} TN={11}; original path UNKNOWN={12}; source bytes={13} B directory bytes={14} calls={15} candidates={16} elapsed-ms={17}; synthetic only' -f
    $b402Lfn.TP,$b402Lfn.FP,$b402Lfn.FN,$b402Lfn.TN,
    $b402Deletion.TP,$b402Deletion.FP,$b402Deletion.FN,$b402Deletion.TN,
    $b402Orphan.TP,$b402Orphan.FP,$b402Orphan.FN,$b402Orphan.TN,
    $b402UnknownPaths,$b402Returned,$b402Directory,$b402Calls,$b402Retained,$b402Elapsed)
